158	    pub fn mark_dirty(&self) {
159	        self.store.mark_dirty(&self.path);
160	    }
161	
162	    /// Mark this scope as dirty shallowly.
163	    pub fn mark_dirty_shallow(&self) {
164	        self.store.mark_dirty_shallow(&self.path);
165	    }
