65	    where
66	        T: IndexMut<Idx> + 'static + IndexSelector<Idx>,
67	        Lens: Readable<Target = T> + 'static,
68	    {
69	        T::scope_selector(self.into_selector(), &index)
70	            .map_writer(move |write| IndexWrite { index, write })
71	            .into()
72	    }
73	}
