/// and can be subscribed to and marked dirty separately.
///
/// Each node tracks two kinds of subscribers:
/// - `shallow_subscribers` are only notified when the value at *exactly* this path changes.
/// - `deep_subscribers` are notified when the value at this path *or any of its descendants* changes.
///
/// When a value is written to, the node it was written to (and, for a recursive write, its whole
/// subtree) is marked dirty, and every ancestor's deep subscribers are notified as well since the
/// value they observe transitively changed.
#[derive(Clone, Default)]
pub(crate) struct SelectorNode {
    /// Reactive contexts that only care about changes to this exact path.
    shallow_subscribers: HashSet<ReactiveContext>,
    /// Reactive contexts that care about changes to this path or any of its descendants.
    deep_subscribers: HashSet<ReactiveContext>,
    children: HashMap<PathKey, SelectorNode>,
}

impl SelectorNode {
    /// Get an existing selector node by its path.
    fn get(&self, path: &[PathKey]) -> Option<&SelectorNode> {
        let [first, rest @ ..] = path else {
            return Some(self);
        };
        self.children.get(first).and_then(|child| child.get(rest))
    }

    /// Get an existing selector node by its path mutably.
    fn get_mut(&mut self, path: &[PathKey]) -> Option<&mut SelectorNode> {
        let [first, rest @ ..] = path else {
            return Some(self);
        };
        self.children
            .get_mut(first)
            .and_then(|child| child.get_mut(rest))
    }

    /// Get a selector mutably or create one if it doesn't exist. This is used when subscribing to
    /// a path that may not exist yet.
    fn get_mut_or_default(&mut self, path: &[PathKey]) -> &mut SelectorNode {
        let [first, rest @ ..] = path else {
            return self;
        };
        self.children
