mod tests {
    use super::*;
    use dioxus::prelude::*;
    use std::sync::atomic::{AtomicUsize, Ordering};

    /// Marking a path dirty must notify the deep subscribers of its ancestors, the deep subscribers
    /// of its descendants, and the shallow subscribers of its descendants, each exactly once. In
    /// particular, an ancestor's deep subscriber must not be notified again while walking the
    /// descendants of the written path.
    #[test]
    fn mark_dirty_marks_descendants_without_remarking_ancestors() {
        fn app() -> Element {
            rsx! {}
        }
        let mut dom = VirtualDom::new(app);
        dom.rebuild_in_place();

        dom.runtime().in_scope(ScopeId::APP, || {
            let subscriptions = StoreSubscriptions::new();

            // Each reactive context counts how many times it is notified so we can detect any
            // double-notifications.
            let root_count = Arc::new(AtomicUsize::new(0));
            let child_count = Arc::new(AtomicUsize::new(0));
            let leaf_count = Arc::new(AtomicUsize::new(0));

            let make_rc = |count: Arc<AtomicUsize>| {
                ReactiveContext::new_with_callback(
                    move || {
                        count.fetch_add(1, Ordering::SeqCst);
                    },
                    ScopeId::APP,
                    std::panic::Location::caller(),
                )
            };

            let root_rc = make_rc(root_count.clone());
            let child_rc = make_rc(child_count.clone());
            let leaf_rc = make_rc(leaf_count.clone());

            // A deep subscriber at the root, a deep subscriber two levels down, and a shallow
            // subscriber three levels down.
            root_rc.subscribe(subscriptions.deep_subscribers(&[]));
            child_rc.subscribe(subscriptions.deep_subscribers(&[1, 2]));
            leaf_rc.subscribe(subscriptions.shallow_subscribers(&[1, 2, 3]));

            // Writing to `[1]` should notify each of the three subscribers exactly once:
            // - the root deep subscriber, because `[1]` is a descendant of the root,
            // - the deep subscriber at `[1, 2]`, because it is a descendant of `[1]`,
            // - the shallow subscriber at `[1, 2, 3]`, because it is a descendant of `[1]`.
            subscriptions.mark_dirty(&[1]);

            assert_eq!(root_count.load(Ordering::SeqCst), 1);
            assert_eq!(child_count.load(Ordering::SeqCst), 1);
            assert_eq!(leaf_count.load(Ordering::SeqCst), 1);
        });
    }
